/*
  FICHEIRO: src/components/ui/InputField/InputField.jsx (VERSÃO COMPLETA E CORRIGIDA)
  Adiciona a lógica para formatar o campo de telefone e para exibir mensagens de erro.
*/
import React from 'react';
import styles from './InputField.module.css';

const InputField = ({ label, type = 'text', name, placeholder, value, onChange, error, readOnly = false }) => {
  
  const handleInputChange = (e) => {
    let { value } = e.target;
    // Se o campo for do tipo 'tel', remove tudo o que não for número
    if (type === 'tel') {
      value = value.replace(/[^0-9]/g, '');
    }
    // Chama a função onChange do componente pai com o valor formatado
    onChange({ ...e, target: { ...e.target, name, value } });
  };

  return (
    <div className={styles.group}>
      <label htmlFor={name} className={styles.label}>{label}</label>
      <input
        type={type}
        id={name}
        name={name}
        placeholder={placeholder}
        className={`${styles.input} ${error ? styles.errorInput : ''}`}
        value={value}
        onChange={handleInputChange} // Usa o novo handler
        readOnly={readOnly}
      />
      {/* Exibe a mensagem de erro se ela existir */}
      {error && <p className={styles.errorMessage}>{error}</p>}
    </div>
  );
};

export default InputField;
